        .append(userCouponDO.getCouponTemplateId())
        .append("_")
        .append(userCouponDO.getId())
        .toString();
stringRedisTemplate.opsForZSet().remove(String.format(USER_COUPON_TEMPLATE_LIST_KEY, UserContext.getUserId()), userCouponItemCacheKey);
```

