                .eq(CouponSettlementDO::getUserId, Long.parseLong(UserContext.getUserId()))
                .eq(CouponSettlementDO::getStatus, 0);
        CouponSettlementDO couponSettlementDO = CouponSettlementDO.builder()
                .status(2)
